let scr;

function update() {
  if (!ticks) {
    p = vec(50, 50);
    v = vec();
    floors = [vec(50, 70)];
    jumpWay = jumpPower = floorAppDist = 1;
  }
  const origin = vec(p);
  const incomingY = v.y;
  const motion = window.motionPort.move({tick:ticks,position:p.x,facing:jumpWay,normalDisplacement:v.x});
  p.x += motion.displacement;
  p.y += incomingY;
  v.y += input.isPressed ? 0.05 : 0.1;
  score += scr = (p.y < 30 ? (30 - p.y) * 0.1 : 0) + difficulty * 0.1;
  if ((floorAppDist -= scr) < 0) {
    floorAppDist = rnd(99);
    floors.push(vec(rnd(99), -9));
  }
  p.y += scr;
  color("blue");
  floors = floors.filter((f) => {
    f.y += scr;
    box(f, 33, 7);
    return f.y < 99;
  });
  if (motion.ownsMotion) {
