    let landed = false;
    for (let index = 0; index < count; index++) {
      p.x += motion.displacement / count;
      if (!landed) p.y += incomingY / count;
      color("transparent");
      while (box(p,7,7).isColliding.rect.blue) {
        p.y--; v.set(); jumpPower = 1; landed = true;
      }
    }
  }
  color("transparent");
  for (;;) {
    if (!box(p, 7, 7).isColliding.rect.blue) {
      break;
    }
    p.y--;
    v.set();
    jumpPower = 1;
  }
  color("green");
  box(p, 7, 7);
  if (input.isJustPressed) {
    play("jump");
    v.x = jumpWay *= -1;
    v.y = -3 * jumpPower;
    jumpPower *= 0.7;
  }
  if (p.y > 99) {
    play("explosion");
    end();
  }
}


